// Données inventées : aucun fournisseur ni compte bancaire réel.
return [
  { reference: 'F-001', iban: 'DE36 0000 0000 0000 0000 01', bic: '', bank_name: '' },
  { reference: 'F-002', iban: '', bic: '', bank_name: '' },
  { reference: 'F-003', iban: 'DE36000000000000000001', bic: '', bank_name: '' },
  { reference: 'F-004', iban: 'DE00000000000000000001', bic: '', bank_name: '' },
].map(json => ({ json }));

// Le modèle accepte un petit lot explicite ; il ne découpe ni ne relance en silence.
const items = $input.all();
if (!items.length || items.length > 100) {
  throw new Error('Fournir de 1 à 100 lignes. Aucun appel effectué.');
}
const normalize = (value) => value.replace(/[\s-]/g, '').toUpperCase();
const ibans = [];
const occurrences = new Map();
const rows = items.map((item, index) => {
  const original = item.json;
  const raw = original.iban;
  const row = {
    record: index + 1,
    original,
    normalized_iban: null,
    request_index: null,
    reason: 'missing_iban',
    duplicate_in_batch: false,
  };
  if (raw == null || raw === '') return row;
  if (typeof raw !== 'string') {
    row.reason = 'iban_must_be_text';
    return row;
  }
  const normalized = normalize(raw);
  if (!normalized) return row;
  row.normalized_iban = normalized;
  occurrences.set(normalized, (occurrences.get(normalized) || 0) + 1);
  if (raw.length > 64) {
    row.reason = 'input_too_long';
    return row;
  }
  row.request_index = ibans.length;
  row.reason = 'awaiting_reference_check';
  ibans.push(raw);
  return row;
});
for (const row of rows) {
  row.duplicate_in_batch = (occurrences.get(row.normalized_iban) || 0) > 1;
}
// Les noms et autres colonnes restent ici. Le nœud HTTP n'envoie que ibans.
return [{ json: { rows, ibans } }];

const lot = $('Préparer le lot').first().json;
const normalize = (value) => value.replace(/[\s-]/g, '').toUpperCase();
const object = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const text = (value) => typeof value === 'string' && value.trim().length > 0;
let results = [];
if (lot.ibans.length) {
  const response = $input.first().json;
  if (response.statusCode !== 200 || !object(response.body) || !Array.isArray(response.body.results)) {
    throw new Error('Réponse API inattendue : aucun rapport partiel produit.');
  }
  results = response.body.results;
  if (results.length !== lot.ibans.length) {
    throw new Error('Nombre de résultats incohérent : aucun rapport partiel produit.');
  }
  // Vérifier tous les résultats avant de restituer la moindre ligne.
  results.forEach((result, index) => {
    if (!object(result) || typeof result.iban !== 'string' ||
        normalize(result.iban) !== normalize(lot.ibans[index]) || typeof result.valid !== 'boolean') {
      throw new Error('Correspondance ou verdict API incohérent : aucun rapport partiel produit.');
    }
  });
}

function classify(original, result) {
  if (!result.valid) return { decision: 'ask_supplier', reason: 'invalid_iban', proposal: null };
  const check = result.bank_code_check ?? {};
  const checks = result.checks ?? {};
  const bic = result.bic ?? {};
  if (![check, checks, bic].every(object)) {
    throw new Error('Structure de référence inattendue : aucun rapport partiel produit.');
  }
  if (checks.national_check_digits === 'fail') {
    return { decision: 'ask_supplier', reason: 'national_check_failed', proposal: null };
  }
  if (check.status === 'not_in_register' && check.authoritative === true && check.reason === 'not_allocated') {
    return { decision: 'ask_supplier', reason: 'bank_code_not_allocated', proposal: null };
  }
  if (check.retired === true) {
    return { decision: 'review', reason: 'retired_code_no_automatic_replacement', proposal: null };
  }
  if (check.status !== 'verified' || check.authoritative !== true ||
      result.bank_code_holder !== 'confirmed' || checks.bank_code !== 'pass' || checks.bic !== 'pass' ||
      bic.authoritative !== true || bic.basis !== 'national_register' ||
      typeof bic.code !== 'string' || !/^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$/.test(bic.code)) {
    return { decision: 'review', reason: 'insufficient_reference_evidence', proposal: null };
  }
  if (![check.register, check.as_of, bic.source, bic.as_of].every(text)) {
    return { decision: 'review', reason: 'missing_source_or_date', proposal: null };
  }
  // Une valeur existante n'est jamais remplacée, même si sa forme est inattendue.
  if ((original.bic != null && typeof original.bic !== 'string') ||
      (original.bank_name != null && typeof original.bank_name !== 'string')) {
    return { decision: 'review', reason: 'existing_field_requires_review', proposal: null };
  }
  const previous = (original.bic ?? '').trim().toUpperCase();
  if (previous && previous !== bic.code) {
    return { decision: 'review', reason: 'existing_bic_differs', proposal: null };
  }
  const proposal = {};
  if (!previous) proposal.bic = bic.code;
  if (!(original.bank_name ?? '').trim() && text(bic.bank_name)) proposal.bank_name = bic.bank_name;
  if (!Object.keys(proposal).length) {
    return { decision: 'review', reason: 'no_missing_field_to_propose', proposal: null };
  }
  return { decision: 'enrichment_proposal', reason: 'register_fields_for_review', proposal };
}

return lot.rows.map((row) => {
  const result = row.request_index === null ? null : results[row.request_index];
  let finding = result === null
    ? { decision: 'review', reason: row.reason, proposal: null }
    : classify(row.original, result);
  if (row.duplicate_in_batch && finding.decision === 'enrichment_proposal') {
    finding = { decision: 'review', reason: 'duplicate_iban_in_batch', proposal: null };
  }
  return {
    json: {
      record: row.record,
      original: row.original,
      review: {
        ...finding,
        normalized_iban: row.normalized_iban,
        duplicate_in_batch: row.duplicate_in_batch,
        payment_authorized: false,
        result,
      },
    },
    pairedItem: { item: 0 },
  };
});
